import{describe,it,expect,vi}from"vitest";import{SpeechSynthesisAdapter}from"../../frontend/js-modules/voice/speech-synthesis-adapter.js";function fakeSynth(e){return{cancel:vi.fn(),speak:vi.fn(),getVoices:()=>e}}class FakeUtterance{constructor(e){this.text=e,this.rate=1,this.pitch=1}}describe("SpeechSynthesisAdapter",()=>{it("returns false and does nothing when synthesis is unavailable",()=>{const e=new SpeechSynthesisAdapter({synth:null,UtteranceCtor:FakeUtterance});expect(e.speak("hello")).toBe(!1)}),it("finds an exact language match",()=>{const e=[{lang:"en-US"},{lang:"hi-IN"}],t=new SpeechSynthesisAdapter({synth:fakeSynth(e),UtteranceCtor:FakeUtterance});expect(t.findVoiceForLanguage("hi-IN")).toBe(e[1])}),it("falls back to a base-language match when no exact match exists",()=>{const e=[{lang:"en-US"},{lang:"hi-IN"}],t=new SpeechSynthesisAdapter({synth:fakeSynth(e),UtteranceCtor:FakeUtterance});expect(t.findVoiceForLanguage("hi")).toBe(e[1])}),it("returns null when no voice matches",()=>{const e=new SpeechSynthesisAdapter({synth:fakeSynth([{lang:"en-US"}]),UtteranceCtor:FakeUtterance});expect(e.findVoiceForLanguage("ta-IN")).toBeNull()}),it("cancels any in-progress speech before speaking the next utterance",()=>{const e=fakeSynth([]);new SpeechSynthesisAdapter({synth:e,UtteranceCtor:FakeUtterance}).speak("hello"),expect(e.cancel).toHaveBeenCalled(),expect(e.speak).toHaveBeenCalled()})});